<script setup>
import { computed, inject } from 'vue'
import { t } from '../state'
import Icon from '../components/Icon.vue'
import Brand from '../components/Brand.vue'
import RevenueChart from './RevenueChart.vue'
import EmptyState from './EmptyState.vue'
import { amount, date, status, time } from './format'
const c = inject('console')
const o = computed(() => c.overview.value)
const range = computed(() => ({ today: t('今日', 'Today'), '7d': t('近 7 天', 'Last 7 days'), '30d': t('近 30 天', 'Last 30 days') })[c.period.value])
const channels = [{ key: 'alipay', zh: '支付宝', en: 'Alipay' }, { key: 'wechat', zh: '微信支付', en: 'WeChat Pay' }, { key: 'paypal', zh: 'PayPal', en: 'PayPal' }, { key: 'stripe', zh: 'Stripe', en: 'Stripe' }]
</script>
<template>
  <div class="console-page-heading"><div><h2>{{ t('收款概览', 'Payment overview') }}</h2><p>{{ t('每一笔交易，每一个状态，尽在掌握。', 'Your payments and their status, in one place.') }}</p></div><div class="heading-control"><Icon name="calendar" :size="16" /><select v-model="c.period.value" :aria-label="t('统计时间范围', 'Reporting period')"><option value="today">{{ t('今日', 'Today') }}</option><option value="7d">{{ t('近 7 天', 'Last 7 days') }}</option><option value="30d">{{ t('近 30 天', 'Last 30 days') }}</option></select></div></div>
  <div class="console-stat-grid" :aria-busy="c.busy.value">
    <article class="hig-card metric-card metric-primary"><div><span>{{ range }}{{ t('收款金额', ' revenue') }}</span><Icon name="wallet" :size="19" /></div><strong><small>¥</small>{{ o ? amount(o.revenue_cents) : '—' }}</strong><p><span class="metric-pill blue">CNY</span><span>{{ t('仅统计已确认到账', 'Confirmed payments only') }}</span></p></article>
    <article class="hig-card metric-card"><div><span>{{ t('支付成功订单', 'Successful payments') }}</span><Icon name="success" :size="19" /></div><strong>{{ o?.paid_count ?? '—' }}<small>{{ t('笔', 'orders') }}</small></strong><p><span class="metric-pill green">{{ o?.paid_ratio != null ? `${o.paid_ratio}%` : '—' }}</span><span>{{ t('期间创建订单的成功率', 'Success rate of orders created') }}</span></p></article>
    <article class="hig-card metric-card"><div><span>{{ t('收款配置', 'Payment configurations') }}</span><Icon name="network" :size="19" /></div><strong>{{ o ? o.enabled_config_count : '—' }}<small>/ {{ o?.config_count || 0 }}</small></strong><p><span class="mini-led" :class="o?.channel_ready && o?.channel_enabled ? 'green' : 'amber'"></span><span>{{ o?.channel_ready && o?.channel_enabled ? t('支付宝已启用', 'Alipay enabled') : t('支付宝待配置或已暂停', 'Alipay requires setup or is paused') }}</span></p></article>
    <article class="hig-card metric-card"><div><span>{{ t('异常回调', 'Failed callbacks') }}</span><Icon name="webhook" :size="19" /></div><strong :class="{ 'text-amber': o?.callbacks.failed }">{{ o?.callbacks.failed ?? '—' }}<small>{{ t('笔', 'events') }}</small></strong><p><button class="text-link" @click="c.navigate('webhook', { status: 'failed' })">{{ t('查看投递队列', 'View delivery queue') }}<Icon name="arrow" :size="13" /></button></p></article>
  </div>
  <div class="overview-chart-grid">
    <article class="hig-card trend-card"><div class="card-heading"><div><h3>{{ t('收款趋势', 'Revenue trend') }}</h3><p>{{ t('按支付确认时间统计 · 北京时间', 'By payment confirmation time · UTC+8') }}</p></div><div class="segmented-control"><button v-for="period in ['today','7d','30d']" :key="period" :class="{ selected: c.period.value === period }" :aria-pressed="c.period.value === period" @click="c.period.value = period">{{ ({ today: t('今日', 'Day'), '7d': t('7 天', '7D'), '30d': t('30 天', '30D') })[period] }}</button></div></div><div class="trend-total"><b>¥ {{ o ? amount(o.revenue_cents) : '—' }}</b><span>{{ range }} · {{ o?.paid_count ?? 0 }} {{ t('笔交易', 'payments') }}</span></div><RevenueChart :series="o?.trend || []" :period="c.period.value" /></article>
    <article class="hig-card channel-share"><div class="card-heading"><div><h3>{{ t('收款渠道分布', 'Payment distribution') }}</h3><p>{{ range }} · CNY</p></div><Icon name="network" :size="18" /></div><div class="channel-share-total"><span>{{ t('累计确认收款', 'Lifetime revenue') }}</span><b>¥ {{ o ? amount(o.lifetime_revenue_cents) : '—' }}</b></div><div v-for="ch in channels" :key="ch.key" class="share-row"><div><span class="brand-small" :class="ch.key"><Brand :name="ch.key" /></span><b>{{ t(ch.zh, ch.en) }}</b><span>{{ `¥ ${amount(o?.distribution?.[ch.key])}` }}</span></div><div class="share-track"><i :class="ch.key" :style="{ width: o?.revenue_cents > 0 ? `${(o.distribution?.[ch.key] || 0) / o.revenue_cents * 100}%` : '0%' }"></i></div></div></article>
  </div>
  <div class="overview-lower-grid">
    <article class="hig-card recent-orders"><div class="card-heading"><div><h3>{{ t('最近交易', 'Recent transactions') }}</h3><p>{{ t('实时追踪最新订单', 'Follow your latest payments') }}</p></div><button class="text-link" @click="c.navigate('orders')">{{ t('全部订单', 'View all') }}<Icon name="chevron" :size="14" /></button></div><div v-if="o?.recent_orders.length" class="table-scroll"><table class="console-table compact-table"><thead><tr><th>{{ t('商品 / 订单号', 'Item / Order') }}</th><th>{{ t('金额', 'Amount') }}</th><th>{{ t('状态', 'Status') }}</th><th>{{ t('创建时间', 'Created') }}</th></tr></thead><tbody><tr v-for="order in o.recent_orders" :key="order.out_trade_no"><td><button class="order-name" @click="c.selectedOrder.value = order">{{ order.subject }}</button><code>{{ order.out_trade_no }}</code></td><td class="numeric">¥ {{ order.amount }}</td><td><span class="state-badge" :class="order.status"><i></i>{{ status(order.status) }}</span></td><td class="muted">{{ date(order.created_at) }}</td></tr></tbody></table></div><EmptyState v-else :title="t('暂无交易记录', 'No transactions yet')" :description="t('创建一笔测试订单，开始检查支付流程。', 'Create a test order to start checking the payment flow.')"><button class="text-link" @click="c.navigate('testpay')">{{ t('创建测试订单', 'Create a test order') }}<Icon name="arrow" :size="14" /></button></EmptyState></article>
    <article class="hig-card service-card"><div class="card-heading"><div><h3>{{ t('服务状态', 'Service status') }}</h3><p>{{ t('最近刷新', 'Last updated') }} {{ time(o?.updated_at) }}</p></div><Icon name="shield" :size="18" /></div><div class="service-row"><Icon name="globe" :size="18" /><span>{{ t('Pay 网关', 'Pay gateway') }}</span><b :class="c.connection.value === 'online' ? 'text-green' : 'text-amber'">{{ c.connection.value === 'online' ? t('已连接', 'Connected') : t('连接中断', 'Disconnected') }}</b></div><div class="service-row"><Icon name="lock" :size="18" /><span>RSA2 {{ t('回调验签', 'verification') }}</span><b class="text-green">{{ t('强制开启', 'Required') }}</b></div><div class="service-row"><Icon name="webhook" :size="18" /><span>{{ t('回调工作进程', 'Callback worker') }}</span><b :class="o?.worker_last_seen && o.updated_at-o.worker_last_seen<45 ? 'text-green' : 'text-amber'">{{ o?.worker_last_seen && o.updated_at-o.worker_last_seen<45 ? t('运行中', 'Running') : t('未检测到心跳', 'No heartbeat') }}</b></div><div class="service-row"><Icon name="timer" :size="18" /><span>{{ t('等待投递', 'Pending delivery') }}</span><b>{{ o?.callbacks.pending || 0 }} {{ t('笔', 'events') }}</b></div><button class="service-link" @click="c.navigate('logs')">{{ t('查看系统日志', 'View event log') }}<Icon name="arrow" :size="15" /></button></article>
  </div>
</template>
